def copy_fallow_marks(apps, schema_editor):
    """Give every use area that carries the old fallow mark one period with no dates.

    A period with no start month and no end month is fallow in every month,
    which is what the mark meant. A use area that already has a period is left
    as it is, so running this twice adds nothing.
    """
    Parcel = apps.get_model("parcels", "Parcel")
    FallowPeriod = apps.get_model("parcels", "FallowPeriod")
    already = set(FallowPeriod.objects.values_list("parcel_id", flat=True))
    FallowPeriod.objects.bulk_create(
        [
            FallowPeriod(parcel_id=pk)
            for pk in Parcel.objects.filter(fallow=True).values_list("pk", flat=True)
            if pk not in already
        ]
    )


def restore_fallow_marks(apps, schema_editor):
    """Going back: a use area with a period that never ends carries the mark again."""
    Parcel = apps.get_model("parcels", "Parcel")
    FallowPeriod = apps.get_model("parcels", "FallowPeriod")
    open_ended = FallowPeriod.objects.filter(end_month__isnull=True).values_list(
        "parcel_id", flat=True
    )
    Parcel.objects.filter(pk__in=list(open_ended)).update(fallow=True)


